class OpenFoodMultiRoleWorkflowEvaluator(BaseEvaluator):
    """Verify the packaged Electron OpenFood workflow from its live local state."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        if controller is None or not hasattr(controller, "run_powershell_script"):
            return EvalResult(status=EvalStatus.ERROR, message="controller.run_powershell_script is required")

        params = dict(context.get("params") or {})
        timeout = float(params.get("timeout", 15) or 15)
        poll_interval = float(params.get("poll_interval", 0.5) or 0.5)
        metadata: dict[str, Any] = {
            "checks": [
                {"id": "orders", "evidence": "live Electron localStorage contains the two exact orders and Delivered overrides"},
                {"id": "merchant_menu", "evidence": "live localStorage records the target menu item unavailable"},
                {"id": "merchant_restaurant", "evidence": "live localStorage records the target restaurant closed"},
                {"id": "support_ticket", "evidence": "live localStorage contains the exact Open support ticket"},
                {"id": "final_cart", "evidence": "live localStorage contains the Vietnamese fee filter, target restaurant, exact quantities, and no coupon"},
                {"id": "openfood_window", "evidence": "a visible OpenFood-compatible desktop window remains present"},
            ],
            "unscored_app_limitation": {
                "id": "courier_route",
                "reason": "Snapshot 1 packaged OpenFood implements Accept route and Next step as toast-only handlers and stores no resulting courier state.",
            },
            "params": params,
            "read_only": True,
        }

        last_failure: AssertionError | None = None
        last_error: Exception | None = None
        deadline = time.time() + max(timeout, 0.1)
        while True:
            try:
                local_state = self._evaluate_local_state(controller, params)
                metadata["local_state"] = local_state
                last_failure = None
                last_error = None
                break
            except AssertionError as exc:
                last_failure = exc
            except Exception as exc:
                last_error = exc
            if time.time() >= deadline:
                break
            time.sleep(poll_interval)

        if last_failure is not None:
            metadata["failure_reason"] = str(last_failure)
            return EvalResult(status=EvalStatus.FAIL, message=str(last_failure), metadata=metadata)
        if last_error is not None:
            metadata["failure_reason"] = str(last_error)
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"OpenFood multi-role evaluation failed: {last_error}",
                metadata=metadata,
            )

        try:
            metadata["ui"] = self._evaluate_ui(context, controller, params)
        except AssertionError as exc:
            metadata["failure_reason"] = str(exc)
            return EvalResult(status=EvalStatus.FAIL, message=str(exc), metadata=metadata)
        except Exception as exc:
            metadata["failure_reason"] = str(exc)
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"OpenFood final UI evaluation failed: {exc}",
                metadata=metadata,
            )

        return EvalResult(
            status=EvalStatus.PASS,
            message="OpenFood orders, merchant changes, support ticket, and final cart passed against live Electron state",
            metadata=metadata,
        )

    @staticmethod
    def _evaluate_local_state(controller: Any, params: Mapping[str, Any]) -> dict[str, Any]:
        script_path = Path(__file__).with_name("checks") / "openfood_local_state.ps1"
        script = script_path.read_text(encoding="utf-8")
        result = controller.run_powershell_script(script, timeout=120)
        returncode = int(result.get("returncode", -1))
        output = str(result.get("output", "")).strip()
        if returncode != 0:
            raise RuntimeError(output or f"guest OpenFood local-state check failed with exit code {returncode}")
        payload = json.loads(output)
        state = dict(payload.get("state") or {})
        menu_ids = dict(payload.get("menu_id_by_name") or {})
        restaurant_ids = dict(payload.get("restaurant_id_by_name") or {})
        user_ids = dict(payload.get("user_id_by_name") or {})
        failures: list[str] = []

        customer_name = str(params.get("expected_customer_name") or "")
        restaurant_name = str(params.get("expected_order_restaurant") or "")
        customer_id = str(user_ids.get(customer_name) or "lucas")
        restaurant_id = str(restaurant_ids.get(restaurant_name) or "r1")
        orders = list(state.get("createdOrders") or [])
        order_status = dict(state.get("orderStatus") or {})

        def expected_item_ids(spec: Mapping[str, Any]) -> dict[str, int]:
            result: dict[str, int] = {}
            for name, quantity in dict(spec.get("items") or {}).items():
                item_id = str(menu_ids.get(f"{restaurant_id}|{name}") or "")
                if not item_id:
                    failures.append(f"seed data did not expose a menu id for {name!r}")
                else:
                    result[item_id] = int(quantity)
            return result

        def actual_items(order: Mapping[str, Any]) -> dict[str, int]:
            return {str(item_id): int(quantity) for item_id, quantity in list(order.get("items") or [])}

        if len(orders) != 2:
            failures.append(f"createdOrders contained {len(orders)} orders, expected exactly 2")
        else:
            second_order, first_order = orders[0], orders[1]
            for label, order, spec in (
                ("first coupon order", first_order, dict(params.get("first_order") or {})),
                ("second no-coupon reorder", second_order, dict(params.get("second_order") or {})),
            ):
                if str(order.get("userId") or "") != customer_id:
                    failures.append(f"{label} userId was {order.get('userId')!r}, expected {customer_id!r}")
                if str(order.get("restaurantId") or "") != restaurant_id:
                    failures.append(f"{label} restaurantId was {order.get('restaurantId')!r}, expected {restaurant_id!r}")
                expected_items = expected_item_ids(spec)
                if actual_items(order) != expected_items:
                    failures.append(f"{label} items were {actual_items(order)!r}, expected {expected_items!r}")
                expected_status = str(spec.get("status") or "")
                actual_status = str(order_status.get(str(order.get("id") or "")) or order.get("status") or "")
                if expected_status and actual_status.upper() != expected_status.upper():
                    failures.append(f"{label} status was {actual_status!r}, expected {expected_status!r}")

            first_coupon = str(dict(params.get("first_order") or {}).get("coupon_code") or "")
            if str(first_order.get("notes") or "") != f"Coupon {first_coupon} applied":
                failures.append(f"first coupon order notes were {first_order.get('notes')!r}")
            if str(second_order.get("notes") or "") != "No special notes":
                failures.append(f"second no-coupon order notes were {second_order.get('notes')!r}")

        menu_spec = dict(params.get("menu_item_state") or {})
        menu_restaurant_id = str(restaurant_ids.get(str(menu_spec.get("restaurant") or "")) or restaurant_id)
        menu_item_id = str(menu_ids.get(f"{menu_restaurant_id}|{menu_spec.get('name') or ''}") or "m3")
        actual_available = dict(state.get("menuAvailability") or {}).get(menu_item_id)
        if actual_available is not bool(menu_spec.get("is_available")):
            failures.append(f"menuAvailability[{menu_item_id!r}] was {actual_available!r}, expected {bool(menu_spec.get('is_available'))!r}")

        closed_spec = dict(params.get("closed_restaurant") or {})
        closed_id = str(restaurant_ids.get(str(closed_spec.get("name") or "")) or "r4")
        actual_open = dict(state.get("restaurantOpen") or {}).get(closed_id)
        if actual_open is not bool(closed_spec.get("is_open")):
            failures.append(f"restaurantOpen[{closed_id!r}] was {actual_open!r}, expected {bool(closed_spec.get('is_open'))!r}")

        ticket_spec = dict(params.get("support_ticket") or {})
        matching_tickets = [
            ticket for ticket in list(state.get("tickets") or [])
            if str(ticket.get("userId") or "") == customer_id
            and str(ticket.get("subject") or "") == str(ticket_spec.get("subject") or "")
            and str(ticket.get("body") or "") == str(ticket_spec.get("description") or "")
            and str(ticket.get("status") or "").upper() == str(ticket_spec.get("status") or "").upper()
        ]
        if len(matching_tickets) != 1:
            failures.append(f"found {len(matching_tickets)} exact matching support tickets, expected 1")

        final_restaurant = "Santana Row Banh Mi Market No. 12 San Jose CA"
        final_restaurant_id = str(restaurant_ids.get(final_restaurant) or "r2")
        final_items = {
            str(menu_ids.get(f"{final_restaurant_id}|Golden San Jose Pho Tai Rice") or "m11"): 2,
            str(menu_ids.get(f"{final_restaurant_id}|Golden San Jose Pho Tai Soup") or "m12"): 2,
        }
        cart = {str(line.get("itemId") or ""): int(line.get("qty") or 0) for line in list(state.get("cart") or [])}
        filters = dict(state.get("filters") or {})
        if str(state.get("userId") or "") != customer_id:
            failures.append(f"final userId was {state.get('userId')!r}, expected {customer_id!r}")
        if str(state.get("selectedRestaurantId") or "") != final_restaurant_id:
            failures.append(f"final selectedRestaurantId was {state.get('selectedRestaurantId')!r}, expected {final_restaurant_id!r}")
        if cart != final_items:
            failures.append(f"final cart was {cart!r}, expected {final_items!r}")
        if str(state.get("activeCoupon") or ""):
            failures.append(f"final activeCoupon was {state.get('activeCoupon')!r}, expected no coupon")
        expected_filters = {"q": "banh mi", "cuisine": "Vietnamese", "sort": "fee"}
        actual_filters = {key: str(filters.get(key) or "") for key in expected_filters}
        if actual_filters != expected_filters:
            failures.append(f"final filters were {actual_filters!r}, expected {expected_filters!r}")

        route_spec = dict(params.get("courier_route") or {})
        route_label = str(route_spec.get("label") or "D-346")
        route_matches = [
            row for row in payload.get("courier_route_seeds", [])
            if isinstance(row, Mapping) and str(row.get("id") or "") == route_label
        ]
        route_seed = dict(route_matches[0]) if len(route_matches) == 1 else {}
        if not route_seed:
            failures.append(f"Snapshot 1 seed did not expose courier route {route_label}")

        if failures:
            raise AssertionError("; ".join(failures))
        return {
            "source": payload.get("source"),
            "storage_key": payload.get("storage_key"),
            "process_id": payload.get("process_id"),
            "candidate_count": payload.get("candidate_count"),
            "orders": orders,
            "order_status": order_status,
            "menu_availability": {menu_item_id: actual_available},
            "restaurant_open": {closed_id: actual_open},
            "support_ticket": matching_tickets[0],
            "final_state": {
                "userId": state.get("userId"),
                "selectedRestaurantId": state.get("selectedRestaurantId"),
                "filters": filters,
                "cart": state.get("cart"),
                "activeCoupon": state.get("activeCoupon"),
            },
            "courier_route_seed": route_seed,
            "courier_state_note": "The packaged app has no state mutation for courier action buttons, so their clicks are not independently observable.",
        }

